<script setup>
import {computed,onMounted,ref,watch} from 'vue';
import api from '../services/api';
import AppIcon from '../components/common/AppIcon.vue';
import TransactionDetailModal from '../components/transactions/TransactionDetailModal.vue';

const props=defineProps({resource:String});
const rows=ref([]),search=ref(''),loading=ref(false),timer=ref(),columns=ref([]),showForm=ref(false),editing=ref(null),detailId=ref(null),error=ref('');
const options=ref({suppliers:[],customers:[],products:[]}),outstanding=ref([]);
const configs={
 products:[['name','Name','text'],['sku','SKU','text'],['barcode','Barcode','text'],['unit','Unit','text'],['purchase_price','Purchase price','number'],['sale_price','Sale price','number'],['minimum_stock_level','Minimum stock','number'],['opening_stock','Opening stock','number']],
 suppliers:[['name','Supplier name','text'],['contact_person','Contact person','text'],['phone','Phone','text'],['email','Email','email'],['opening_balance','Opening balance','number']],
 customers:[['name','Customer name','text'],['phone','Phone','text'],['email','Email','email'],['opening_balance','Opening balance','number']],
 payments:[['payment_date','Voucher date','date'],['payment_type','Voucher direction','payment_type'],['supplier_id','Pay to supplier','supplier'],['customer_id','Receive from customer','customer'],['document_id','Apply to transaction','document'],['amount','Amount','number'],['payment_method','Payment method','payment_method'],['reference_number','Reference number','text']],
 'stock-movements':[['adjustment_date','Date','date'],['product_id','Product','product'],['adjustment_type','Adjustment type','adjustment_type'],['quantity','Quantity','number'],['reason','Reason','text']]
};
const preferred={
 products:['serial','name','sku','barcode','unit','current_stock','sale_price','is_active'],
 suppliers:['serial','name','contact_person','phone','email','opening_balance','is_active'],
 customers:['serial','name','phone','email','opening_balance','is_walk_in','is_active'],
 purchases:['serial','purchase_number','purchase_date','supplier_name','grand_total','paid_amount','due_amount','payment_status','status'],
 sales:['serial','sale_number','sale_date','customer_name','grand_total','paid_amount','due_amount','payment_status','status'],
 payments:['serial','payment_number','payment_date','party_name','amount','payment_method','payment_type','is_reversed'],
 'stock-movements':['serial','movement_date','product_name','product_sku','movement_type','reference_number','quantity_in','quantity_out','stock_after']
};
const canForm=computed(()=>!!configs[props.resource]),detailResource=computed(()=>['purchases','sales','payments'].includes(props.resource)),form=ref({});
function defaults(){form.value={is_active:true,unit:'piece',purchase_price:0,sale_price:0,minimum_stock_level:0,opening_stock:0,opening_balance:0,payment_date:new Date().toISOString().slice(0,10),adjustment_date:new Date().toISOString().slice(0,10),payment_method:'cash',payment_type:'supplier_payment',adjustment_type:'increase',document_id:''};outstanding.value=[]}
async function load(){loading.value=true;try{const result=(await api.get('/'+props.resource,{params:{search:search.value}})).data.data;rows.value=(result.data||result).map((x,index)=>({...x,serial:index+1,supplier_name:x.supplier?.name,customer_name:x.customer?.name,party_name:x.supplier?.name||x.customer?.name,product_name:x.product?.name,product_sku:x.product?.sku}));columns.value=preferred[props.resource]||(rows.value.length?Object.keys(rows.value[0]).filter(k=>!['id','product_id','supplier_id','customer_id','purchase_id','sale_id','created_by','deleted_at','updated_at','description','notes'].includes(k)&&!k.endsWith('_id')&&typeof rows.value[0][k]!=='object').slice(0,8):[])}finally{loading.value=false}}
async function loadOptions(){for(const x of ['suppliers','customers','products'])try{options.value[x]=(await api.get('/'+x,{params:{per_page:100,active:1}})).data.data.data}catch{}}
function create(){editing.value=null;defaults();showForm.value=true}function edit(row){editing.value=row.id;form.value={...row};showForm.value=true}
async function loadOutstanding(){outstanding.value=[];form.value.document_id='';if(props.resource!=='payments')return;const partyId=form.value.payment_type==='supplier_payment'?form.value.supplier_id:form.value.customer_id;if(!partyId)return;outstanding.value=(await api.get('/payments/outstanding',{params:{payment_type:form.value.payment_type,party_id:partyId}})).data.data}
async function save(){error.value='';try{let endpoint='/'+props.resource;if(props.resource==='stock-movements')endpoint='/stock-adjustments';const payload={...form.value};if(props.resource==='payments'&&payload.document_id){payload[payload.payment_type==='supplier_payment'?'purchase_id':'sale_id']=payload.document_id}delete payload.document_id;if(editing.value)await api.put(endpoint+'/'+editing.value,payload);else await api.post(endpoint,payload);showForm.value=false;await load()}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'Unable to save.'}}
watch(()=>props.resource,()=>{showForm.value=false;detailId.value=null;load();loadOptions()});watch(search,()=>{clearTimeout(timer.value);timer.value=setTimeout(load,300)});onMounted(()=>{defaults();load();loadOptions()});
</script>
<template>
<div class="page-head"><div><span class="eyebrow">Records</span><h1>{{resource.replace('-',' ').replace(/\b\w/g,c=>c.toUpperCase())}}</h1><p class="page-subtitle">Search, review, and manage {{resource.replace('-',' ')}}.</p></div><div class="page-actions"><RouterLink v-if="resource==='purchases'||resource==='sales'" class="btn with-icon" :to="`/${resource}/new`"><AppIcon name="plus"/>New {{resource.slice(0,-1)}}</RouterLink><button v-if="canForm" class="with-icon" @click="create"><AppIcon name="plus"/>{{resource==='stock-movements'?'New adjustment':'New record'}}</button></div></div>
<form v-if="showForm" class="panel record-form" @submit.prevent="save"><div class="panel-head"><div><h2>{{editing?'Edit':'Create'}} record</h2><p>Complete the required information below.</p></div><button type="button" class="icon-only secondary" @click="showForm=false"><AppIcon name="close"/></button></div><div v-if="error" class="error">{{error}}</div><div class="form-grid"><div class="field" v-for="[key,label,type] in configs[resource]" v-show="!((key==='supplier_id'&&form.payment_type!=='supplier_payment')||(key==='customer_id'&&form.payment_type!=='customer_payment'))"><label>{{label}}</label>
<select v-if="type==='supplier'||type==='customer'||type==='product'" v-model="form[key]" :required="type==='product'||(type==='supplier'&&form.payment_type==='supplier_payment')||(type==='customer'&&form.payment_type==='customer_payment')" @change="loadOutstanding"><option value="">Select…</option><option v-for="o in options[type+'s']" :value="o.id">{{o.name}}</option></select>
<select v-else-if="type==='payment_type'" v-model="form[key]" @change="form.supplier_id='';form.customer_id='';loadOutstanding()"><option value="supplier_payment">Money out — Payment voucher</option><option value="customer_payment">Money in — Receipt voucher</option></select>
<select v-else-if="type==='document'" v-model="form[key]"><option value="">General / opening balance</option><option v-for="doc in outstanding" :value="doc.id">{{doc.number}} · Due {{Number(doc.due).toLocaleString(undefined,{minimumFractionDigits:2})}}</option></select>
<select v-else-if="type==='payment_method'" v-model="form[key]"><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="card">Card</option><option value="other">Other</option></select>
<select v-else-if="type==='adjustment_type'" v-model="form[key]"><option value="increase">Increase stock</option><option value="decrease">Decrease stock</option></select>
<input v-else v-model="form[key]" :type="type" :step="type==='number'?'.001':undefined" required></div></div><div class="form-actions"><button class="with-icon"><AppIcon name="plus"/>Save record</button><button type="button" class="secondary" @click="showForm=false">Cancel</button></div></form>
<div class="toolbar search-box"><AppIcon name="search"/><input v-model="search" placeholder="Search records…"></div>
<div class="panel list-panel"><table><thead><tr><th v-for="c in columns">{{c.replaceAll('_',' ')}}</th><th v-if="detailResource||['products','suppliers','customers'].includes(resource)">Actions</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td v-for="c in columns"><span v-if="c.includes('status')||c==='is_reversed'" class="status" :class="r[c]==='paid'||r[c]==='completed'||r[c]===false?'success':r[c]==='partial'?'warning':'neutral'">{{c==='is_reversed'?(r[c]?'Reversed':'Active'):r[c]}}</span><template v-else>{{r[c]}}</template></td><td v-if="detailResource||['products','suppliers','customers'].includes(resource)"><div class="row-actions"><button v-if="detailResource" class="icon-only secondary" title="View and print" @click="detailId=r.id"><AppIcon name="eye"/></button><button v-if="['products','suppliers','customers'].includes(resource)" class="icon-only secondary" title="Edit" @click="edit(r)"><AppIcon name="edit"/></button></div></td></tr><tr v-if="!loading&&!rows.length"><td :colspan="columns.length+1"><div class="empty-state">No records found.</div></td></tr></tbody></table></div>
<TransactionDetailModal v-if="detailId" :resource="resource" :id="detailId" @close="detailId=null"/>
</template>
